-- Production credit grant evidence probe. All fixtures and transitions roll back.
-- No payment provider calls occur.
begin;
set local lock_timeout='3s';
set local statement_timeout='20s';
create temporary table payment_audit_results(label text, passed boolean) on commit drop;
grant insert,select on payment_audit_results to authenticated,anon,service_role;
create function pg_temp.ok(value boolean,label text) returns void language plpgsql security invoker as $fn$
begin
 if value is distinct from true then raise exception 'Payment audit failed: %',label; end if;
 insert into pg_temp.payment_audit_results values(label,true);
end; $fn$;
create function pg_temp.is(actual anyelement,expected anyelement,label text) returns void language plpgsql security invoker as $fn$
begin perform pg_temp.ok(actual is not distinct from expected,label); end; $fn$;
create function pg_temp.throws_ok(statement text,code text,unused text,label text) returns void language plpgsql security invoker as $fn$
begin
 begin execute statement;
 exception when others then
   if sqlstate=code and (unused is null or sqlerrm=unused) then perform pg_temp.ok(true,label); return; end if;
   raise;
 end;
 raise exception 'Expected denied operation: %',label;
end; $fn$;
set local search_path=public,pg_temp;
grant execute on function pg_temp.ok(boolean,text), pg_temp.is(anyelement,anyelement,text), pg_temp.throws_ok(text,text,text,text) to authenticated,anon,service_role;

insert into auth.users(id,email,aud,role,is_anonymous,created_at) values('e8610001-0000-4000-8000-000000000001','refund-source-audit@example.invalid','authenticated','authenticated',false,now());
update public.profiles set credits=0,promotional_credits=0 where id='e8610001-0000-4000-8000-000000000001';
insert into public.transactions(id,user_id,razorpay_order_id,amount,credits,status) values('e8610002-0000-4000-8000-000000000001','e8610001-0000-4000-8000-000000000001','order_source_1',10000,100,'created');
insert into public.transactions(id,user_id,razorpay_order_id,amount,credits,status) values('e8610002-0000-4000-8000-000000000002','e8610001-0000-4000-8000-000000000001','order_source_2',10000,100,'created');
insert into public.transactions(id,user_id,razorpay_order_id,amount,credits,status) values('e8610002-0000-4000-8000-000000000003','e8610001-0000-4000-8000-000000000001','order_source_3',10000,100,'created');
insert into public.transactions(id,user_id,razorpay_order_id,amount,credits,status) values('e8610002-0000-4000-8000-000000000004','e8610001-0000-4000-8000-000000000001','order_source_4',10000,100,'created');
insert into public.transactions(id,user_id,razorpay_order_id,amount,credits,status) values('e8610002-0000-4000-8000-000000000005','e8610001-0000-4000-8000-000000000001','order_source_5',10000,100,'created');
insert into public.transactions(id,user_id,razorpay_order_id,amount,credits,status) values('e8610002-0000-4000-8000-000000000006','e8610001-0000-4000-8000-000000000001','order_source_6',10000,100,'created');
insert into public.transactions(id,user_id,razorpay_order_id,amount,credits,status) values('e8610002-0000-4000-8000-000000000007','e8610001-0000-4000-8000-000000000001','order_source_7',10000,100,'created');
insert into public.transactions(id,user_id,razorpay_order_id,amount,credits,status) values('e8610002-0000-4000-8000-000000000008','e8610001-0000-4000-8000-000000000001','order_source_8',10000,100,'created');
set local role service_role;
select public.add_credits('e8610001-0000-4000-8000-000000000001',100,'e8610002-0000-4000-8000-000000000001','pay_source_1');
select public.add_credits('e8610001-0000-4000-8000-000000000001',100,'e8610002-0000-4000-8000-000000000002','pay_source_2');
select public.add_credits('e8610001-0000-4000-8000-000000000001',100,'e8610002-0000-4000-8000-000000000003','pay_source_3');
select public.add_credits('e8610001-0000-4000-8000-000000000001',100,'e8610002-0000-4000-8000-000000000004','pay_source_4');
select public.add_credits('e8610001-0000-4000-8000-000000000001',100,'e8610002-0000-4000-8000-000000000005','pay_source_5');
select public.add_credits('e8610001-0000-4000-8000-000000000001',100,'e8610002-0000-4000-8000-000000000006','pay_source_6');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),600,'six captured fixtures granted');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000001','pay_source_1','disp_first_won','dispute_won',0,3000)->>'status'),'no_change','won before open records terminal state');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000001','pay_source_1','disp_first_won','dispute_open',0,3000)->>'status'),'duplicate_event','delayed open cannot reopen won dispute');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),600,'won-first ordering leaves balance unchanged');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000002','pay_source_2','disp_refund','dispute_open',0,3000)->>'status'),'partially_reversed','open dispute reverses its amount');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),570,'open dispute deducts 30 credits');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000002','pay_source_2','rfnd_later','refund',5000,0)->>'status'),'partially_reversed','refund adds to outstanding dispute');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),520,'refund and dispute conserve both amounts');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000002','pay_source_2','disp_refund','dispute_won',0,3000)->>'status'),'partially_restored','stale won snapshot restores only dispute');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),550,'known refund remains reversed');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000002','pay_source_2','rfnd_old','refund',2000,0)->>'status'),'no_change','older smaller refund does not lower floor');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000002','pay_source_2','rfnd_later','refund',5000,0)->>'status'),'duplicate_event','refund redelivery is inert');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),550,'refund replays cannot restore credits');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000003','pay_source_3','disp_a','dispute_open',0,7000)->>'status'),'partially_reversed','first large dispute');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000003','pay_source_3','disp_b','dispute_open',0,6000)->>'status'),'reversed','combined dispute capped to purchase amount');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),450,'combined disputes never debit over purchase');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000003','pay_source_3','disp_a','dispute_won',0,7000)->>'status'),'partially_restored','winning one dispute preserves the other');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),490,'only remaining disputed amount stays reversed');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000003','pay_source_3','disp_b','dispute_won',0,6000)->>'status'),'restored','winning both restores captured grant');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),550,'complete dispute restore grants exactly original amount');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000004','pay_source_4','disp_new_refund','dispute_open',0,2000)->>'status'),'partially_reversed','open before newer refund snapshot');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000004','pay_source_4','disp_new_refund','dispute_won',5000,2000)->>'status'),'partially_reversed','won with newer refund can increase net reversal');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),500,'new refund evidence on won is retained');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000004','pay_source_4','disp_new_refund','dispute_open',7000,2000)->>'status'),'partially_reversed','delayed open can raise refund floor without reopening dispute');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),480,'won state survives newer refund evidence');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000004','pay_source_4','disp_new_refund','dispute_won',7000,2000)->>'status'),'duplicate_event','repeated won snapshot inert');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000005','pay_source_5','invalid','refund',null,0)->>'status'),'invalid_request','null refund total refused');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000005','pay_source_5','invalid','refund',-1,0)->>'status'),'invalid_request','negative refund refused');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000005','pay_source_5','invalid','dispute_open',0,0)->>'status'),'invalid_request','zero dispute refused');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000005','pay_source_5','invalid','refund',10001,0)->>'status'),'invalid_amount','over-purchase refund refused');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000005','pay_source_5','invalid','dispute_open',0,10001)->>'status'),'invalid_amount','over-purchase dispute refused');
select pg_temp.is((select count(*) from public.razorpay_credit_adjustment_sources where transaction_id='e8610002-0000-4000-8000-000000000005'),0::bigint,'invalid events create no source state');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000005','pay_wrong','bad','refund',1,0)->>'status'),'payment_conflict','wrong payment rejected');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000005','pay_source_5','disp_first_won','dispute_open',0,3000)->>'status'),'source_conflict','source ID cannot move between purchases');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000001','pay_source_1','disp_first_won','dispute_won',0,4000)->>'status'),'source_conflict','dispute amount cannot change silently');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),480,'invalid source updates cannot move balance');
update public.profiles set credits=0 where id='e8610001-0000-4000-8000-000000000001';
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000005','pay_source_5','rfnd_spent','refund',10000,0)->>'status'),'reversed','refund after spending still debits full purchase');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),-100,'spent credits produce debt');
select public.reconcile_razorpay_credit_purchase_adjustment('e8610002-0000-4000-8000-000000000006','refund:legacy-source','pay_source_6',2000,'reverse','Audit legacy');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000006','pay_source_6','legacy_new','refund',3000,0)->>'status'),'legacy_adjustment_requires_review','legacy aggregate requires explicit review');
select pg_temp.is((select count(*) from public.razorpay_credit_adjustment_sources where transaction_id='e8610002-0000-4000-8000-000000000006'),0::bigint,'legacy guard leaves source state empty');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),-120,'legacy guard does not guess balance');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000007','pay_source_7','disp_before_capture','dispute_open',0,3000)->>'status'),'partially_reversed','pre-grant dispute voids purchase');
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000007','pay_source_7','disp_before_capture','dispute_won',0,3000)->>'status'),'restored','pre-grant win remains bookkeeping only');
select pg_temp.is(public.add_credits('e8610001-0000-4000-8000-000000000001',100,'e8610002-0000-4000-8000-000000000007','pay_source_7'),false,'void purchase cannot be captured after restore');
select pg_temp.is((select credits from public.profiles where id='e8610001-0000-4000-8000-000000000001'),-120,'ungranted reversal and restore never move credits');
select pg_temp.is((select bool_and(base_credit_delta=0) from public.credit_purchase_adjustments where transaction_id='e8610002-0000-4000-8000-000000000007'),true,'pre-grant ledger records zero deltas');
reset role;
update public.transactions set mobile_product_id='magicbooklet.credits.100' where id='e8610002-0000-4000-8000-000000000008';
set local role service_role;
select pg_temp.is((public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000008','pay_source_8','mobile','refund',1000,0)->>'status'),'provider_mismatch','mobile ledger excluded');
reset role;
set local role anon;
select pg_temp.throws_ok($q$select public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000001','pay_source_1','denied','refund',100,0)$q$,'42501',null,'anon cannot invoke source reconciliation');
select pg_temp.throws_ok($q$select * from public.razorpay_credit_adjustment_sources$q$,'42501',null,'anon cannot read provider source state');
reset role;
set local role authenticated;
select pg_temp.throws_ok($q$select public.reconcile_razorpay_credit_source('e8610002-0000-4000-8000-000000000001','pay_source_1','denied','refund',100,0)$q$,'42501',null,'authenticated cannot invoke source reconciliation');
select pg_temp.throws_ok($q$select * from public.razorpay_credit_adjustment_sources$q$,'42501',null,'authenticated cannot read provider source state');
reset role;
set local role service_role;
select pg_temp.throws_ok($q$delete from public.razorpay_credit_adjustment_sources$q$,'42501',null,'service client cannot bypass source state machine');
reset role;
select jsonb_build_object('passed',count(*),'checks',jsonb_agg(label order by label)) as payment_audit from pg_temp.payment_audit_results;
rollback;
